window.getFurnaceIconHtml = (level, size = 32) => {
  if (!level || level === "N/A" || level === "") return `<span style="color:var(--text-muted); font-size:13px; font-weight:bold;">🔥 N/A</span>`;
  
  const rawStr = level.toString().trim().toUpperCase();
  let fcNum = null;
  let furnaceNum = null;
  
  // 1. Check for explicit "FC", "FIRE CRYSTAL", or "STOVE_LV_" prefix followed by number 1-10
  const fcMatch = rawStr.match(/(?:FC|FIRE\s*CRYSTAL|STOVE_LV_)\s*[\.-]?\s*(\d+)/i);
  if (fcMatch) {
     const parsedFc = parseInt(fcMatch[1], 10);
     if (parsedFc >= 1 && parsedFc <= 10) {
        fcNum = parsedFc;
     } else if (parsedFc > 30 && parsedFc <= 40) {
        fcNum = parsedFc - 30;
     } else if (parsedFc > 40 && parsedFc <= 80) {
        fcNum = Math.ceil((parsedFc - 30) / 5);
     }
  } else {
     // 2. If no explicit FC prefix, extract the FIRST number in the string
     const firstNumMatch = rawStr.match(/(\d+)/);
     if (firstNumMatch) {
        const numVal = parseInt(firstNumMatch[1], 10);
        if (numVal > 30 && numVal <= 40) {
           fcNum = numVal - 30;
        } else if (numVal > 40 && numVal <= 80) {
           fcNum = Math.ceil((numVal - 30) / 5);
        } else if (numVal >= 1 && numVal <= 30) {
           furnaceNum = numVal;
        }
     }
  }

  // Render 3D Gem Faceted Fire Crystal Star Badge if fcNum is valid (FC 1 - 10)
  if (fcNum && fcNum >= 1 && fcNum <= 10) {
     const fcGlowMap = {
       1: 'rgba(239,68,68,0.85)',    // Crimson Red
       2: 'rgba(249,115,22,0.85)',   // Flame Orange
       3: 'rgba(234,179,8,0.85)',    // Sunburst Yellow
       4: 'rgba(16,185,129,0.85)',   // Emerald Green
       5: 'rgba(6,182,212,0.85)',    // Ice Cyan
       6: 'rgba(59,130,246,0.85)',   // Sapphire Blue
       7: 'rgba(139,92,246,0.85)',   // Amethyst Purple
       8: 'rgba(236,72,153,0.85)',   // Magenta Rose
       9: 'rgba(132,204,22,0.95)',   // Kryptonite Lime
       10: 'rgba(255,215,0,0.9)'    // Imperial Gold
     };
     const glow = fcGlowMap[fcNum];
     const canvasDisplaySize = Math.round(size * 1.35);
     const marginOffset = Math.round((canvasDisplaySize - size) / 2);
     return `<canvas class="fc-unified-badge" data-fc="${fcNum}" data-size="${size}" style="display:inline-block; vertical-align:middle; width:${canvasDisplaySize}px; height:${canvasDisplaySize}px; cursor:pointer; user-select:none; -webkit-user-select:none; margin:-${marginOffset}px 2px; transition:filter 0.25s ease;" title="Fire Crystal ${fcNum} (FC ${fcNum})"></canvas>`;
  }

  // Render Modern Standard Furnace Badge (Furnace 1 to 30)
  const fn = furnaceNum || 30;
  return `<span class="furnace-level-badge" title="Furnace Level ${fn}" style="display:inline-flex; align-items:center; gap:6px; background:linear-gradient(135deg, rgba(30,41,59,0.8), rgba(15,23,42,0.9)); border:1px solid rgba(249,115,22,0.4); padding:3px 8px; border-radius:10px; font-weight:800; font-size:${Math.max(11, Math.round(size*0.36))}px; color:#ffffff; box-shadow:0 4px 12px rgba(249,115,22,0.15); white-space:nowrap; vertical-align:middle;">
    <span style="filter:drop-shadow(0 0 4px #f97316);">🔥</span> Lv ${fn}
  </span>`;
};

window.renderFurnaceSelectHtml = (id = 'manualFurnaceLevel', selectedVal = '', extraStyles = '') => {
  const norm = (selectedVal || '').toString().trim().toUpperCase();
  let selFc = null;
  let selLv = null;

  const fcMatch = norm.match(/(?:FC|FIRE\s*CRYSTAL|STOVE_LV_)\s*[\.-]?\s*(\d+)/i);
  if (fcMatch) {
     const pFc = parseInt(fcMatch[1], 10);
     if (pFc >= 1 && pFc <= 10) selFc = pFc;
     else if (pFc > 30 && pFc <= 40) selFc = pFc - 30;
     else if (pFc > 40 && pFc <= 80) selFc = Math.ceil((pFc - 30) / 5);
  } else {
     const firstNumMatch = norm.match(/(\d+)/);
     if (firstNumMatch) {
        const numVal = parseInt(firstNumMatch[1], 10);
        if (numVal > 30 && numVal <= 40) selFc = numVal - 30;
        else if (numVal > 40 && numVal <= 80) selFc = Math.ceil((numVal - 30) / 5);
        else if (numVal >= 1 && numVal <= 30) selLv = numVal;
     }
  }
  
  let options = `
    <option value="" ${(!selFc && !selLv) ? 'selected' : ''}>Select Furnace Level (Optional)</option>
    <optgroup label="🔥 Fire Crystal (FC) Levels">
  `;
  
  for (let fc = 10; fc >= 1; fc--) {
    const val = `FC ${fc}`;
    const isSel = (selFc === fc);
    options += `<option value="${val}" ${isSel ? 'selected' : ''}>FC ${fc} (Fire Crystal ${fc})</option>`;
  }
  
  options += `
    </optgroup>
    <optgroup label="🪵 Standard Furnace Levels">
  `;
  
  for (let lv = 30; lv >= 1; lv--) {
    const val = `${lv}`;
    const isSel = (!selFc && selLv === lv);
    options += `<option value="${val}" ${isSel ? 'selected' : ''}>Furnace ${lv}</option>`;
  }
  options += `</optgroup>`;

  return `<select id="${id}" style="width:100%; padding:10px 14px; border-radius:8px; border:1px solid var(--border); background:var(--bg-main); color:var(--text-main); font-size:15px; box-sizing:border-box; ${extraStyles}">${options}</select>`;
};

// --- Security Helpers ---
window.escapeHTML = (str) => {
  if (typeof str !== 'string') str = String(str || '');
  return str.replace(/[&<>'"]/g, tag => ({
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      "'": '&#39;',
      '"': '&quot;'
  }[tag]));
};

window.translateWosApiError = (msg, code = null) => {
  if (typeof msg === 'object' && msg !== null) {
    if (msg.code !== undefined) code = msg.code;
    msg = msg.message || msg.rawMsg || JSON.stringify(msg);
  }
  let cleanMsg = (msg || '').toString().trim();
  
  // Extract code from message if embedded (e.g. "[Code 15030]")
  const extractedCodeMatch = cleanMsg.match(/\[Code\s*(\d+)\]/i);
  if (!code && extractedCodeMatch) {
    code = extractedCodeMatch[1];
  }
  // Strip duplicate code badges from raw text
  cleanMsg = cleanMsg.replace(/\[Code\s*\d+\]\s*/gi, '').trim();

  const codeNum = typeof code === 'number' ? code : (code ? parseInt(code, 10) : null);
  const codeBadge = codeNum ? `[Code ${codeNum}] ` : '';

  if (codeNum === 15030 || codeNum === 101031008 || codeNum === 15006 || cleanMsg.includes("未登录") || cleanMsg.includes("登录态已失效") || cleanMsg.includes("已失效") || cleanMsg.includes("token失效")) {
    return `${codeBadge}30-Day session token expired. Please enter a fresh in-game code to renew.`;
  }
  if (codeNum === 101031005 || cleanMsg.includes("验证码发送次数已达上限") || cleanMsg.includes("次数已达上限") || cleanMsg.includes("上限")) {
    return `${codeBadge}Daily verification code limit reached for this Game ID today. Please wait a while before requesting another code, or enter Chief Name manually.`;
  }
  if (codeNum === 101031002 || cleanMsg.includes("验证码错误") || cleanMsg.includes("验证码无效") || cleanMsg.includes("验证码已过期")) {
    return `${codeBadge}Invalid or expired verification code. Please check your in-game mailbox or request a new code.`;
  }
  if (codeNum === 101031001 || cleanMsg.includes("角色不存在") || cleanMsg.includes("用户不存在") || cleanMsg.includes("未找到")) {
    return `${codeBadge}Player ID not found. Please double-check your numeric Game ID in Whiteout Survival.`;
  }
  if (codeNum === 40001 || codeNum === 40003 || cleanMsg.includes("频繁") || cleanMsg.includes("稍后再试")) {
    return `${codeBadge}Too many requests. Please wait a moment and try again.`;
  }
  if (cleanMsg.includes("参数错误")) {
    return `${codeBadge}Invalid request parameters. Please verify your Game ID.`;
  }
  if (cleanMsg.includes("系统错误") || cleanMsg.includes("服务异常")) {
    return `${codeBadge}Game server is currently busy. Please try again shortly.`;
  }

  // Catch-all for any untranslated Chinese characters
  if (/[\u4e00-\u9fa5]/.test(cleanMsg)) {
    return `${codeBadge}30-Day session expired or profile unavailable. Please verify with a fresh in-game code.`;
  }

  if (!cleanMsg) return `${codeBadge}An error occurred communicating with the game server.`;
  return codeBadge ? `${codeBadge}${cleanMsg}` : cleanMsg;
};

window.formatTimeActiveShort = (str) => {
    if (!str || typeof str !== 'string') return str;
    let formatted = str.replace(/\s*years?/gi, 'y')
              .replace(/\s*months?/gi, 'm')
              .replace(/\s*days?/gi, 'd')
              .replace(/,\s*/g, ' ')
              .replace(/\s+/g, ' ')
              .trim();
              
    let filtered = formatted.split(' ').filter(part => !part.match(/^0[ymd]$/i)).join(' ');
    return filtered === '' ? '0d' : filtered;
};

window.calculateTimeActive = (dateInput) => {
   if (!dateInput) return 'Unknown';
   const startDate = new Date(dateInput);
   if (isNaN(startDate.getTime())) return window.formatTimeActiveShort(dateInput.toString());
   
   const now = new Date();
   let years = now.getFullYear() - startDate.getFullYear();
   let months = now.getMonth() - startDate.getMonth();
   let days = now.getDate() - startDate.getDate();
   
   if (days < 0) {
      months--;
      const prevMonthLastDay = new Date(now.getFullYear(), now.getMonth(), 0).getDate();
      days += prevMonthLastDay;
   }
   if (months < 0) {
      years--;
      months += 12;
   }
   
   if (years < 0) return '0d';
   
   let parts = [];
   if (years > 0) parts.push(`${years}y`);
   if (months > 0) parts.push(`${months}m`);
   if (days > 0 || parts.length === 0) parts.push(`${days}d`);
   
   return parts.join(' ');
};

window.formatDateForInput = (dateStr) => {
   if (!dateStr) return '';
   const d = new Date(dateStr);
   if (isNaN(d.getTime())) return '';
   const year = d.getFullYear();
   const month = String(d.getMonth() + 1).padStart(2, '0');
   const day = String(d.getDate()).padStart(2, '0');
   return `${year}-${month}-${day}`;
};


