// Fetch Mercenary Boss Progress from Firebase node mercenary/boss_progress
window.mercenaryBossProgressCache = null;

window.fetchMercenaryBossProgress = async () => {
    if (window.mercenaryBossProgressCache) return window.mercenaryBossProgressCache;
    const defaultData = { lv1: 0, lv2: 0, lv3: 0, lv4: 0, lv5: 0 };
    try {
        let snap = await get(ref(db, 'mercenary/boss_progress'));
        if (!snap.exists()) {
            snap = await get(ref(db, 'mercenary_boss_progress'));
        }
        if (snap.exists()) {
            const data = snap.val();
            window.mercenaryBossProgressCache = {
                lv1: parseInt(data.lv1) || 0,
                lv2: parseInt(data.lv2) || 0,
                lv3: parseInt(data.lv3) || 0,
                lv4: parseInt(data.lv4) || 0,
                lv5: parseInt(data.lv5) || 0,
                updatedAt: data.updatedAt || Date.now()
            };
            return window.mercenaryBossProgressCache;
        }
    } catch(e) { console.warn("Firebase mercenary boss progress read error:", e); }
    window.mercenaryBossProgressCache = defaultData;
    return defaultData;
};

window.saveMercenaryBossProgress = async (bossData) => {
    if (!bossData || typeof bossData !== 'object') return false;
    try {
        const payload = {
            lv1: parseInt(bossData.lv1) || 0,
            lv2: parseInt(bossData.lv2) || 0,
            lv3: parseInt(bossData.lv3) || 0,
            lv4: parseInt(bossData.lv4) || 0,
            lv5: parseInt(bossData.lv5) || 0,
            updatedAt: Date.now()
        };
        // Save to mercenary/boss_progress which is authorized under mercenary rules
        await set(ref(db, 'mercenary/boss_progress'), payload);
        await set(ref(db, 'mercenary_boss_progress'), payload).catch(() => null);
        window.mercenaryBossProgressCache = payload;
        return true;
    } catch(e) {
        console.error("Error writing mercenary boss progress to Firebase:", e);
        return false;
    }
};

window.adjustBossProgressCount = (bossKey, delta) => {
    const input = document.getElementById(`boss_input_${bossKey}`);
    if (input) {
        let current = parseInt(input.value) || 0;
        let nextVal = Math.max(0, current + delta);
        input.value = nextVal;
    }
};

window.saveAllBossProgress = async () => {
    const keys = ['lv1', 'lv2', 'lv3', 'lv4', 'lv5'];
    const payload = {};
    keys.forEach(k => {
        const input = document.getElementById(`boss_input_${k}`);
        payload[k] = input ? Math.max(0, parseInt(input.value) || 0) : 0;
    });
    
    const ok = await window.saveMercenaryBossProgress(payload);
    if (ok) {
        if (window.showToast) window.showToast("🎉 All 5 boss unlock counts saved successfully!", "success");
        if (typeof window.activeViewFunc === 'function') {
            window.activeViewFunc();
        } else if (window.views && window.views.mercenaryAdmin) {
            window.views.mercenaryAdmin();
        }
    } else {
        if (window.showToast) window.showToast("Failed to save boss counts. Check your network or admin permissions.", "error");
    }
};

window.syncBossProgressFromMasters = async (rosterMasterCount) => {
    const bp = {
        lv1: rosterMasterCount,
        lv2: rosterMasterCount,
        lv3: rosterMasterCount,
        lv4: rosterMasterCount,
        lv5: rosterMasterCount
    };
    const ok = await window.saveMercenaryBossProgress(bp);
    if (ok) {
        if (window.showToast) window.showToast(`Auto-filled all boss counts to ${rosterMasterCount}!`, "success");
        if (window.views && window.views.mercenaryAdmin) window.views.mercenaryAdmin();
    }
};

