const authForgotPwBtn = document.getElementById('authForgotPwBtn');
const forgotPasswordModal = document.getElementById('forgotPasswordModal');
const forgotPasswordModalOverlay = document.getElementById('forgotPasswordModalOverlay');
const closeForgotPwBtn = document.getElementById('closeForgotPwBtn');
const forgotPwSubmitBtn = document.getElementById('forgotPwSubmitBtn');
const forgotPwEmail = document.getElementById('forgotPwEmail');
const forgotPwErrorMsg = document.getElementById('forgotPwErrorMsg');

if (authForgotPwBtn) {
  authForgotPwBtn.addEventListener('click', (e) => {
    e.preventDefault();
    forgotPwErrorMsg.style.display = 'none';
    forgotPwEmail.value = authEmail.value; // pre-fill if they started typing
    document.getElementById('authModal').style.display = 'none';
    forgotPasswordModal.style.display = 'block';
    forgotPasswordModalOverlay.style.display = 'block';
  });
}

function closeForgotModal() {
  if (forgotPasswordModal) forgotPasswordModal.style.display = 'none';
  if (forgotPasswordModalOverlay) forgotPasswordModalOverlay.style.display = 'none';
}

if (closeForgotPwBtn) closeForgotPwBtn.addEventListener('click', closeForgotModal);
if (forgotPasswordModalOverlay) forgotPasswordModalOverlay.addEventListener('click', closeForgotModal);

if (forgotPwSubmitBtn) {
  forgotPwSubmitBtn.addEventListener('click', (e) => {
    e.preventDefault();
    const email = forgotPwEmail.value.trim();
    if (!email) {
      forgotPwErrorMsg.textContent = 'Please enter your email address.';
      forgotPwErrorMsg.style.color = 'var(--danger)';
      forgotPwErrorMsg.style.display = 'block';
      return;
    }
    
    forgotPwSubmitBtn.textContent = 'Sending...';
    forgotPwSubmitBtn.disabled = true;
    
    resetPassword(email)
      .then(() => {
        forgotPwErrorMsg.textContent = 'Password reset email sent! Check your inbox.';
        forgotPwErrorMsg.style.color = 'var(--success)';
        forgotPwErrorMsg.style.display = 'block';
        forgotPwSubmitBtn.textContent = 'Send Reset Link';
        forgotPwSubmitBtn.disabled = false;
        setTimeout(() => {
            closeForgotModal();
        }, 2000);
      })
      .catch((error) => {
        forgotPwErrorMsg.textContent = error.message;
        forgotPwErrorMsg.style.color = 'var(--danger)';
        forgotPwErrorMsg.style.display = 'block';
        forgotPwSubmitBtn.textContent = 'Send Reset Link';
        forgotPwSubmitBtn.disabled = false;
      });
  });
}

if(authSubmitBtn) authSubmitBtn.addEventListener('click', async () => {
  authErrorMsg.style.color = 'var(--danger)'; // Reset color to red for login errors
  const email = isGoogleRegistration && pendingGoogleUser ? pendingGoogleUser.email : (authEmail ? authEmail.value.trim().toLowerCase() : "");
  const password = authPassword ? authPassword.value : "";
  const gameId = authGameId ? authGameId.value.trim() : "";
  const dateStarted = authDateStarted ? authDateStarted.value : "";
  
  // Check for manual overrides if API failed
  const manualChiefNameEl = document.getElementById('manualChiefName');
  const manualFurnaceLevelEl = document.getElementById('manualFurnaceLevel');
  const authFurnaceLevelEl = document.getElementById('authFurnaceLevel');
  
  const manualChiefName = manualChiefNameEl ? manualChiefNameEl.value.trim() : "";
  const manualFurnaceLevel = manualFurnaceLevelEl ? manualFurnaceLevelEl.value.trim() : "";
  const selectedFurnaceLevel = authFurnaceLevelEl ? authFurnaceLevelEl.value.trim() : "";
  
  const chiefName = verifiedChiefName || manualChiefName;
  const furnaceLevel = verifiedFurnaceLevel || manualFurnaceLevel || selectedFurnaceLevel || "30";
  
  if (!isGoogleRegistration && (!email || !password)) {
    authErrorMsg.textContent = 'Email and password required.';
    authErrorMsg.style.display = 'block';
    return;
  }
  
  try {
    authSubmitBtn.disabled = true;
    authSubmitBtn.textContent = 'Loading...';
    
    if (isRegistering) {
      if (!gameId) throw new Error('Game ID is required.');
      if (!chiefName) {
        window.renderManualFallback();
        throw new Error('Please click Verify to check your in-game code, or enter your Chief Name below.');
      }
      if (/^\d+$/.test(chiefName.toString().trim()) || chiefName.toString().trim() === gameId.toString().trim()) {
        throw new Error('Chief Name must be your text character name (e.g. BrianDCox), NOT your numeric Game ID.');
      }
      if (!dateStarted) throw new Error('Date You Started Playing is required.');
      
      const useWosAvatar = document.getElementById('regUseWosAvatar')?.checked !== false;
      const avatarUrlToUse = (useWosAvatar && window.verifiedAvatarUrl) ? window.verifiedAvatarUrl : (pendingGoogleUser ? pendingGoogleUser.photoURL : "");
      
      if (isGoogleRegistration && pendingGoogleUser) {
        // Save Google User directly to Firebase Realtime Database
        await set(ref(db, `users/${pendingGoogleUser.uid}`), {
          email: pendingGoogleUser.email,
          gameId: gameId,
          name: chiefName,
          chiefName: chiefName,
          stove_lv: furnaceLevel,
          furnaceLevel: furnaceLevel,
          section: window.verifiedStateKid || "2089",
          avatar_image: window.verifiedAvatarUrl || (pendingGoogleUser.photoURL || ""),
          avatarPreference: useWosAvatar ? 'wos' : (pendingGoogleUser.photoURL ? 'custom' : 'initials'),
          wos_cg_token: window.verifiedCgToken || "",
          dateStarted: dateStarted,
          verifiedAt: new Date().toISOString(),
          centuryGamesVerified: !!window.verifiedCgToken,
          createdAt: new Date().toISOString(),
          authProvider: 'google'
        });
      } else {
        await registerUser(email, password, gameId, chiefName, furnaceLevel);
        
        // Persist verification token and state
        if (auth && auth.currentUser) {
            try {
                await update(ref(db, `users/${auth.currentUser.uid}`), {
                    wos_cg_token: window.verifiedCgToken || "",
                    section: window.verifiedStateKid || "2089",
                    stove_lv: furnaceLevel,
                    avatar_image: window.verifiedAvatarUrl || "",
                    avatarPreference: useWosAvatar ? 'wos' : 'initials',
                    verifiedAt: new Date().toISOString(),
                    centuryGamesVerified: !!window.verifiedCgToken
                });
            } catch(e) { console.warn("Failed to persist token:", e); }
        }
      }

      if (avatarUrlToUse) {
        try {
          await uploadAvatar(gameId, avatarUrlToUse);
          avatarMap[gameId] = avatarUrlToUse;
        } catch(e) { console.warn("Failed to set avatar in DB:", e); }
      }

      // Immediately seed in-memory maps so site never displays 'not found'
      idToNameMap[gameId] = chiefName;
      nameToIdMap[chiefName] = gameId;
      window.idToNameMap[gameId] = chiefName;
      window.nameToIdMap[chiefName] = gameId;
      
      // Auto-enroll in Firebase giftcode_bot & ping backend API
      try {
          await window.enrollGiftcodeBot(gameId, chiefName);
          await refreshIdToNameMap();
          const regToken = await getAuthToken();
          const url = `${API_BASE_URL}?api=registerNewPlayer&gameId=${encodeURIComponent(gameId)}&name=${encodeURIComponent(chiefName)}&dateStarted=${encodeURIComponent(dateStarted)}&level=${encodeURIComponent(furnaceLevel)}${regToken ? '&token=' + encodeURIComponent(regToken) : ''}`;
          fetch(url, { mode: 'no-cors' }).catch(e => console.warn("Failed to ping GAS for registration", e));
      } catch(e) { console.error(e); }

      if (window.triggerNewMemberAlerts) {
          window.triggerNewMemberAlerts({ gameId, chiefName, furnaceLevel, email, createdAt: new Date().toISOString() });
      }

      window.showToast("Account created & character linked!", "success");
    } else {
      await loginUser(email, password);
      window.showToast("Successfully signed in!", "success");
    }
    
    closeAuthModal();
    const onboardingEl = document.getElementById('essentialOnboardingBanner');
    if (onboardingEl) onboardingEl.remove();
    if (typeof window.activeViewFunc === 'function') window.activeViewFunc();
    else views.home();
  } catch(err) {
    authErrorMsg.textContent = err.message;
    authErrorMsg.style.display = 'block';
  } finally {
    authSubmitBtn.disabled = false;
    authSubmitBtn.textContent = isRegistering ? '✨ Create Account' : 'Sign In';
  }
});

async function handleGoogleAuth() {
    try {
        if (authChooseGoogleBtn) authChooseGoogleBtn.disabled = true;
        if (authSignInChooseGoogleBtn) authSignInChooseGoogleBtn.disabled = true;
        
        const userCredential = await loginWithGoogle();
        const user = userCredential.user;
        
        // Check if user is mapped in Realtime Database
        const userRef = ref(db, `users/${user.uid}`);
        const snapshot = await get(userRef);
        
        if (snapshot.exists()) {
            window.showToast("Successfully signed in with Google!", "success");
            closeAuthModal();
            const onboardingEl = document.getElementById('essentialOnboardingBanner');
            if (onboardingEl) onboardingEl.remove();
            if (typeof window.activeViewFunc === 'function') window.activeViewFunc();
            else views.home();
        } else {
            // New user registering with Google!
            isRegistering = true;
            isGoogleRegistration = true;
            pendingGoogleUser = user;
            
            const authGoogleConnectedBanner = document.getElementById('authGoogleConnectedBanner');
            const authGoogleEmailDisplay = document.getElementById('authGoogleEmailDisplay');
            const authEmailPwFields = document.getElementById('authEmailPwFields');
            if (authGoogleEmailDisplay) authGoogleEmailDisplay.textContent = user.email || user.displayName || 'Google Account';
            if (authGoogleConnectedBanner) authGoogleConnectedBanner.style.display = 'block';
            if (authEmailPwFields) authEmailPwFields.style.display = 'none';
            
            if (authModalTitle) authModalTitle.textContent = '✨ Claim Profile & Register';
            if (authToggleText) authToggleText.textContent = 'Already have an account?';
            if (authToggleBtn) authToggleBtn.textContent = 'Sign In';
            
            authErrorMsg.style.display = 'none';
            setAuthStep(2);
        }
    } catch(err) {
        if (err.code !== 'auth/popup-closed-by-user' && err.code !== 'auth/cancelled-popup-request') {
            authErrorMsg.textContent = err.message || 'Google sign-in error';
            authErrorMsg.style.display = 'block';
        }
    } finally {
        if (authChooseGoogleBtn) authChooseGoogleBtn.disabled = false;
        if (authSignInChooseGoogleBtn) authSignInChooseGoogleBtn.disabled = false;
    }
}

const authGoogleBtn = document.getElementById('authGoogleBtn');
if (authChooseGoogleBtn) authChooseGoogleBtn.addEventListener('click', handleGoogleAuth);
if (authSignInChooseGoogleBtn) authSignInChooseGoogleBtn.addEventListener('click', handleGoogleAuth);
if (authGoogleBtn) authGoogleBtn.addEventListener('click', handleGoogleAuth);


