// --- NEW MEMBER ALERT & DISCORD WEBHOOK SYSTEM ---
window.triggerNewMemberAlerts = async (memberRecord) => {
  // Invalidate cache so unread badges update in UI
  window._recentNewMembersCache = null;
  if (typeof window.updateNewMemberBadge === 'function') window.updateNewMemberBadge();

  try {
    const settingsSnap = await get(ref(db, 'config/discordAlerts')).catch(() => null);
    const settings = (settingsSnap && settingsSnap.exists()) ? settingsSnap.val() : {};

    const webhookUrl = settings.discordWebhookUrl ? settings.discordWebhookUrl.trim() : '';
    const alertsEnabled = settings.discordAlertsEnabled !== false;

    if (webhookUrl && alertsEnabled && webhookUrl.startsWith('http')) {
      const recentMembers = await window.getRecentNewMembers();
      
      const rosterFields = recentMembers.slice(0, 10).map((m, idx) => {
        const numPrefix = `${idx + 1}.`;
        let fLvl = '';
        if (m.furnaceLevel && m.furnaceLevel !== 'N/A' && m.furnaceLevel !== '0') {
          const raw = String(m.furnaceLevel).trim();
          const cleanF = raw.toUpperCase().startsWith('FC') ? raw : (parseInt(raw, 10) <= 10 ? `FC ${raw}` : raw);
          fLvl = ` • 🔥 ${cleanF}`;
        }
        const nameClean = String(m.name || 'Member').replace(/^Chief\s+/i, '');
        return {
          name: `${numPrefix} Chief ${nameClean}`,
          value: `🆔 \`${m.gameId || 'N/A'}\`${fLvl} • 🕒 Joined: **${m.createdStr}**`,
          inline: false
        };
      });

      const embedPayload = {
        embeds: [{
          title: "🛡️ ALLIANCE GATEKEEPER — RECENT NEW MEMBERS ROSTER",
          description: `📋 **Active Signups List (Past 7 Days)**:`,
          color: 4242388, // Cyan Accent (#06b6d4)
          fields: rosterFields.length > 0 ? rosterFields : [{ name: "Status", value: "No active signups in the past 7 days.", inline: false }],
          footer: {
            text: `Whiteout Survival Alliance Dashboard • Total Recent Signups: ${recentMembers.length}`
          },
          timestamp: new Date().toISOString()
        }]
      };

      const cleanUrl = webhookUrl.split('?')[0].replace(/\/+$/, '');
      const lastMsgId = settings.lastDiscordMessageId || '';
      let updated = false;

      // Try editing existing message in-place
      if (lastMsgId) {
        try {
          const patchRes = await fetch(`${cleanUrl}/messages/${lastMsgId}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(embedPayload)
          });
          if (patchRes.ok) {
            updated = true;
          }
        } catch(pe) {
          console.warn("Failed to patch existing Discord message:", pe);
        }
      }

      // If no existing message or PATCH failed/deleted, create new post and save message ID
      if (!updated) {
        try {
          const postRes = await fetch(`${cleanUrl}?wait=true`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(embedPayload)
          });
          if (postRes.ok) {
            const data = await postRes.json();
            if (data && data.id) {
              await set(ref(db, 'config/discordAlerts/lastDiscordMessageId'), data.id);
            }
          }
        } catch(postErr) {
          console.warn("Failed to create Discord webhook post:", postErr);
        }
      }
    }
  } catch(e) {
    console.warn("Error sending new member alerts:", e);
  }
};

window.getRecentNewMembers = async () => {
  try {
    const snap = await get(ref(db, 'users')).catch(() => null);
    if (!snap || !snap.exists()) return [];
    const users = snap.val() || {};
    const recent = [];
    const sevenDaysAgo = Date.now() - (7 * 24 * 60 * 60 * 1000);

    for (const [uid, u] of Object.entries(users)) {
      if (!u) continue;
      let createdMs = 0;
      if (u.createdAt) createdMs = new Date(u.createdAt).getTime();
      else if (u.timestamp) createdMs = Number(u.timestamp);

      if (createdMs > 0 && createdMs >= sevenDaysAgo) {
        let cName = u.name || u.chiefName || '';
        const gidStr = String(u.gameId || uid || '').trim();
        if ((!cName || /^\d+$/.test(cName)) && gidStr && window.idToNameMap && window.idToNameMap[gidStr] && !/^\d+$/.test(window.idToNameMap[gidStr])) {
          cName = window.idToNameMap[gidStr];
        } else if ((!cName || /^\d+$/.test(cName)) && u.email && u.email.includes('@')) {
          const emailPrefix = u.email.split('@')[0];
          if (!/^\d+$/.test(emailPrefix)) {
            cName = emailPrefix;
          }
        }
        if (!cName || /^\d+$/.test(cName)) {
          cName = '[Unclaimed Chief]';
        }

        recent.push({
          uid,
          gameId: gidStr,
          name: cName,
          email: u.email || '',
          furnaceLevel: u.stove_lv || u.furnaceLevel || '',
          role: u.role || 'Member',
          createdMs,
          createdStr: new Date(createdMs).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' })
        });
      }
    }

    recent.sort((a, b) => b.createdMs - a.createdMs);
    return recent;
  } catch(e) {
    console.warn("Error fetching recent members:", e);
    return [];
  }
};

window.getMemberTokenStatus = (user) => {
  if (!user || (!user.wos_cg_token && !user.centuryGamesVerified)) {
    return {
      status: 'unverified',
      label: 'Character Unverified',
      desc: 'Verify your in-game mailbox code to enable 30-day automatic stats, furnace level, and avatar syncing.',
      daysLeft: 0,
      alert: true,
      color: '#f59e0b',
      icon: '⚠️'
    };
  }

  const vDate = user.verifiedAt || user.lastSyncedAt;
  if (!vDate) {
    return {
      status: 'active',
      label: 'In-Game Sync Active',
      desc: 'Your 30-day sync token is verified and active for automatic stats syncing.',
      daysLeft: 30,
      alert: false,
      color: '#10b981',
      icon: '🛡️'
    };
  }

  const verifiedMs = new Date(vDate).getTime();
  const elapsedDays = Math.floor((Date.now() - verifiedMs) / (1000 * 60 * 60 * 24));
  const daysLeft = Math.max(0, 30 - elapsedDays);

  if (daysLeft <= 0) {
    return {
      status: 'expired',
      label: '30-Day Sync Token Expired',
      desc: 'Your 30-day token has expired. Enter a new in-game code to keep stats auto-syncing.',
      daysLeft: 0,
      alert: true,
      color: '#ef4444',
      icon: '🚨'
    };
  } else if (daysLeft <= 5) {
    return {
      status: 'expiring_soon',
      label: `Token Expires in ${daysLeft} Day${daysLeft === 1 ? '' : 's'}`,
      desc: `Your 30-day sync token will expire in ${daysLeft} day${daysLeft === 1 ? '' : 's'}. Renew early to avoid sync interruption.`,
      daysLeft: daysLeft,
      alert: true,
      color: '#f59e0b',
      icon: '⏳'
    };
  } else {
    return {
      status: 'active',
      label: `30-Day Sync Active (${daysLeft} Days Left)`,
      desc: `Your 30-day sync token is verified and syncing normally.`,
      daysLeft: daysLeft,
      alert: false,
      color: '#10b981',
      icon: '🛡️'
    };
  }
};

window.formatRelativeTime = (ts) => {
  if (!ts) return '';
  const diff = Math.max(0, Date.now() - Number(ts));
  const secs = Math.floor(diff / 1000);
  if (secs < 60) return 'Just now';
  const mins = Math.floor(secs / 60);
  if (mins < 60) return `${mins}m ago`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours}h ago`;
  const days = Math.floor(hours / 24);
  if (days < 7) return `${days}d ago`;
  return new Date(ts).toLocaleDateString([], { month: 'short', day: 'numeric' });
};

window.updateNewMemberBadge = async () => {
  document.querySelectorAll('#settingsBtn .new-member-badge, #adminSidebarBtn .new-member-badge, #newMembersSidebarBtn .new-member-badge, .nav-admin-btn .new-member-badge').forEach(b => b.remove());

  const adminAlertsNavBtn = document.getElementById('adminAlertsNavBtn');
  const mobileAlertsBtn = document.getElementById('mobileAlertsBtn');
  if (adminAlertsNavBtn) adminAlertsNavBtn.style.display = 'flex';

  // 1. Check main character token status (if logged in)
  let mainAlert = 0;
  let hasExpiredAlt = false;
  let hasExpiringAlt = false;
  let altAlertsCount = 0;
  let tokenStatus = { status: 'active', alert: false };

  if (currentUser) {
    tokenStatus = window.getMemberTokenStatus(currentUser);
    mainAlert = (tokenStatus.status === 'expired' || tokenStatus.status === 'expiring_soon' || tokenStatus.status === 'unverified') ? 1 : 0;

    // 2. Check linked alts token status
    if (currentUser.linkedGameIds && Array.isArray(currentUser.linkedGameIds) && currentUser.linkedGameIds.length > 0) {
      currentUser.linkedGameIds.forEach(agid => {
        const aTok = currentUser.altTokens ? currentUser.altTokens[agid] : null;
        if (aTok) {
          const aDate = (typeof aTok === 'object' && aTok.verifiedAt) ? new Date(aTok.verifiedAt) : null;
          if (aDate && !isNaN(aDate.getTime())) {
            const elapsed = Math.floor((Date.now() - aDate.getTime()) / (1000 * 60 * 60 * 24));
            const daysLeft = Math.max(0, 30 - elapsed);
            if (daysLeft <= 0) {
              altAlertsCount++;
              hasExpiredAlt = true;
            } else if (daysLeft <= 5) {
              altAlertsCount++;
              hasExpiringAlt = true;
            }
          }
        }
      });
    }
  }

  // 3. Check staff signups if admin
  let staffUnreadCount = 0;
  if (currentUser && window.isAdminUser(currentUser)) {
    const recent = await window.getRecentNewMembers();
    const lastSeen = Number(localStorage.getItem('last_seen_new_member_timestamp') || '0');
    staffUnreadCount = recent.filter(m => m.createdMs > lastSeen).length;
  }

  // 4. Check unread leadership broadcast announcements
  let broadcastUnreadCount = 0;
  try {
    const lastSeenBroadcast = Number(localStorage.getItem('last_seen_broadcast_timestamp') || '0');
    const bSnap = await get(ref(db, 'broadcastAlerts'));
    if (bSnap.exists()) {
      const bVal = bSnap.val() || {};
      for (const item of Object.values(bVal)) {
        if (item && item.timestamp && item.timestamp > lastSeenBroadcast) {
          broadcastUnreadCount++;
        }
      }
    }
  } catch(e) {
    console.warn("Failed to count unread broadcasts:", e);
  }

  const totalAlerts = mainAlert + (altAlertsCount > 0 ? 1 : 0) + staffUnreadCount + broadcastUnreadCount;

  if (mobileAlertsBtn) {
    mobileAlertsBtn.innerHTML = totalAlerts > 0 ? `🔔 Alerts <span style="background:#ef4444; color:#fff; font-size:10px; font-weight:bold; padding:1px 6px; border-radius:10px; margin-left:4px;">${totalAlerts}</span>` : '🔔 Alerts';
  }

  if (adminAlertsNavBtn) {
    let badge = adminAlertsNavBtn.querySelector('.new-member-badge');
    if (totalAlerts > 0) {
      const isCritical = (tokenStatus.status === 'expired' || hasExpiredAlt);
      const isWarning = (tokenStatus.status === 'expiring_soon' || tokenStatus.status === 'unverified' || hasExpiringAlt);
      const alertColor = isCritical ? '#ef4444' : (isWarning ? '#f59e0b' : '#ec4899');
      const alertBg = isCritical ? 'rgba(239,68,68,0.2)' : (isWarning ? 'rgba(245,158,11,0.2)' : 'rgba(236,72,153,0.2)');

      adminAlertsNavBtn.style.position = 'relative';
      adminAlertsNavBtn.style.overflow = 'visible';
      adminAlertsNavBtn.style.background = alertBg;
      adminAlertsNavBtn.style.borderColor = alertColor;
      adminAlertsNavBtn.style.color = alertColor;
      adminAlertsNavBtn.style.animation = 'pulse 2s infinite';
      if (!badge) {
        badge = document.createElement('span');
        badge.className = 'new-member-badge';
        badge.style.cssText = 'position:absolute; top:-6px; right:-6px; min-width:18px; height:18px; background:#ef4444; color:#fff; font-size:10px; font-weight:bold; padding:0 4px; border-radius:9px; box-shadow:0 0 8px rgba(239,68,68,0.7); z-index:10; pointer-events:none; display:flex; align-items:center; justify-content:center; line-height:1;';
        adminAlertsNavBtn.appendChild(badge);
      }
      badge.textContent = `${totalAlerts}`;
    } else {
      if (badge) badge.remove();
      adminAlertsNavBtn.style.background = 'rgba(6,182,212,0.15)';
      adminAlertsNavBtn.style.borderColor = 'rgba(6,182,212,0.4)';
      adminAlertsNavBtn.style.color = '#06b6d4';
      adminAlertsNavBtn.style.animation = 'none';
    }
  }
};

