window.openEditProfileModal = async () => {
  if (!currentUser) return;
  
  let currentFurnace = '30';
  let currentJoinedDate = '';
  let currentBio = '';
  
  try {
    const snap = await get(ref(db, `users/${currentUser.uid}`));
    if (snap.exists()) {
      const uData = snap.val();
      if (uData.stove_lv || uData.furnaceLevel) currentFurnace = (uData.stove_lv || uData.furnaceLevel).toString();
      if (uData.joinedDate) currentJoinedDate = uData.joinedDate;
      if (uData.bio) currentBio = uData.bio;
    }
  } catch(e) { console.error("Firebase fetch error in edit profile:", e); }
  
  if (currentFurnace === '30' || !currentJoinedDate) {
    const rosterData = window.liveData["Chief's List"];
    if (rosterData && rosterData.length > 1) {
       const chiefName = idToNameMap[currentUser.gameId] || currentUser.name || '';
       const p = Object.values(rosterData).find(rp => rp[1] && rp[1].toString().trim() === currentUser.gameId.toString().trim() || (rp[0] && rp[0].toString().toLowerCase() === chiefName.toLowerCase()));
       if (p) {
          if (p[2] && currentFurnace === '30') currentFurnace = p[2].toString();
          if (p[5] && !currentJoinedDate) currentJoinedDate = p[5].toString();
       }
    }
  }

  let isoDate = '';
  if (currentJoinedDate) {
     try {
       const d = new Date(currentJoinedDate);
       if (!isNaN(d.getTime())) isoDate = d.toISOString().split('T')[0];
     } catch(e) {}
  }

  const oldModal = document.getElementById('editProfileModalOverlay');
  if (oldModal && oldModal.parentNode) oldModal.parentNode.removeChild(oldModal);

  const modalOverlay = document.createElement('div');
  modalOverlay.id = 'editProfileModalOverlay';
  modalOverlay.style.cssText = 'position:fixed; inset:0; background:rgba(15,23,42,0.85); backdrop-filter:blur(10px); z-index:99999; display:flex; align-items:center; justify-content:center; animation:fadeIn 0.2s ease;';

  const furnaceSelectHtml = window.renderFurnaceSelectHtml('editProfileFurnaceSelect', currentFurnace, 'margin-top:6px;');

  modalOverlay.innerHTML = `
    <div class="card" style="width:90%; max-width:520px; background:linear-gradient(145deg, rgba(15,23,42,0.95), rgba(30,41,59,0.9)); border:1px solid rgba(56,189,248,0.3); padding:30px; border-radius:20px; box-shadow:0 20px 50px rgba(0,0,0,0.6); text-align:left; animation:zoomIn 0.2s forwards;">
       <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:20px; border-bottom:1px solid rgba(255,255,255,0.1); padding-bottom:12px;">
          <h3 style="margin:0; color:#fff; font-size:22px; font-weight:800; display:flex; align-items:center; gap:8px;">✏️ Edit Member Profile</h3>
          <button id="closeEditProfileBtn" style="background:none; border:none; color:var(--text-muted); font-size:28px; cursor:pointer; line-height:1;">&times;</button>
       </div>

       <div style="display:flex; flex-direction:column; gap:18px;">
          <div>
             <label style="display:block; font-size:13px; font-weight:bold; color:#cbd5e1; margin-bottom:6px; text-transform:uppercase; letter-spacing:0.5px;">📅 Date You Started Playing</label>
             <div style="display:flex; gap:8px; align-items:center;">
                <input type="date" id="editProfileJoinedDateInput" value="${isoDate}" onclick="try{this.showPicker();}catch(e){}" style="flex:1; padding:12px; border-radius:10px; border:1px solid rgba(255,255,255,0.15); background:rgba(15,23,42,0.7); color:#fff; font-size:15px; font-weight:bold; box-sizing:border-box;">
                <button type="button" onclick="try{document.getElementById('editProfileJoinedDateInput').showPicker();}catch(e){}" style="background:rgba(6,182,212,0.15); border:1px solid rgba(6,182,212,0.4); color:var(--accent); border-radius:10px; padding:12px 14px; cursor:pointer; font-size:18px;">📅</button>
             </div>
          </div>

          <div>
             <label style="display:block; font-size:13px; font-weight:bold; color:#cbd5e1; margin-bottom:6px; text-transform:uppercase; letter-spacing:0.5px;">🔥 Furnace Level</label>
             <div style="display:flex; gap:14px; align-items:center;">
                <div style="flex:1;">
                   ${furnaceSelectHtml}
                </div>
                <div id="editProfileBadgePreview" style="min-width:76px; height:76px; background:rgba(255,255,255,0.05); border:1px solid rgba(255,255,255,0.1); border-radius:12px; display:flex; align-items:center; justify-content:center; flex-shrink:0; padding:4px;">
                   ${window.getFurnaceIconHtml(currentFurnace, 76)}
                </div>
             </div>
          </div>

          <div>
             <label style="display:block; font-size:13px; font-weight:bold; color:#cbd5e1; margin-bottom:6px; text-transform:uppercase; letter-spacing:0.5px;">💬 Status Tagline / Motto</label>
             <textarea id="editProfileBioInput" placeholder="Enter your custom motto..." style="width:100%; padding:12px; border-radius:10px; border:1px solid rgba(255,255,255,0.15); background:rgba(15,23,42,0.7); color:#fff; font-size:14px; box-sizing:border-box; resize:vertical; min-height:70px;">${window.escapeHTML(currentBio)}</textarea>
          </div>

          <div style="display:flex; gap:12px; margin-top:10px;">
             <button id="cancelEditProfileBtn" style="flex:1; background:rgba(255,255,255,0.06); border:1px solid rgba(255,255,255,0.2); color:#cbd5e1; padding:12px; border-radius:10px; cursor:pointer; font-weight:bold; font-size:15px;">Cancel</button>
             <button id="saveEditProfileBtn" style="flex:1; background:linear-gradient(135deg, #06b6d4, #3b82f6); color:#fff; border:none; padding:12px; border-radius:10px; cursor:pointer; font-weight:bold; font-size:15px; box-shadow:0 4px 15px rgba(6,182,212,0.4);">Save Changes</button>
          </div>
       </div>
    </div>`;

  document.body.appendChild(modalOverlay);

  const fSelect = document.getElementById('editProfileFurnaceSelect');
  const bPreview = document.getElementById('editProfileBadgePreview');
  if (fSelect && bPreview) {
     fSelect.addEventListener('change', (e) => {
        bPreview.innerHTML = window.getFurnaceIconHtml(e.target.value, 52);
     });
  }

  const closeBtn = document.getElementById('closeEditProfileBtn');
  const cancelBtn = document.getElementById('cancelEditProfileBtn');
  const closeModal = () => { if (document.body.contains(modalOverlay)) document.body.removeChild(modalOverlay); };
  if (closeBtn) closeBtn.onclick = closeModal;
  if (cancelBtn) cancelBtn.onclick = closeModal;

  const saveBtn = document.getElementById('saveEditProfileBtn');
  if (saveBtn) {
     saveBtn.onclick = async () => {
        const newJoinedDate = document.getElementById('editProfileJoinedDateInput').value;
        const newFurnace = document.getElementById('editProfileFurnaceSelect').value || currentFurnace;
        const newBio = document.getElementById('editProfileBioInput').value.trim();

        saveBtn.disabled = true;
        saveBtn.textContent = 'Saving...';

        try {
           const chiefName = (idToNameMap[currentUser.gameId] || currentUser.name || currentUser.chiefName || '').toString().trim();
           const cleanGid = (currentUser.gameId || '').toString().trim();

           // 0. Invalidate in-memory roster cache
           window.rosterCache = null;

           // 1. Update user node in Firebase
           const userRef = ref(db, `users/${currentUser.uid}`);
           await set(userRef, {
              ...currentUser,
              stove_lv: newFurnace,
              furnaceLevel: newFurnace,
              joinedDate: newJoinedDate,
              bio: newBio,
              updatedAt: new Date().toISOString()
           });

           // 2. Update roster_live in Firebase by Chief Name & Game ID
           try {
              const rosterSnap = await get(ref(db, 'roster_live')).catch(() => null);
              let rosterObj = (rosterSnap && rosterSnap.exists()) ? rosterSnap.val() : {};

              let foundKey = null;
              for (const [rk, rv] of Object.entries(rosterObj)) {
                 if (rk.toLowerCase() === chiefName.toLowerCase() ||
                    (rv && rv.name && rv.name.toLowerCase() === chiefName.toLowerCase()) ||
                    (cleanGid && rv && rv.gameId && rv.gameId.toString().trim() === cleanGid)) {
                    foundKey = rk;
                    break;
                 }
              }
              const saveKey = foundKey || chiefName;
              rosterObj[saveKey] = {
                 ...(rosterObj[saveKey] || {}),
                 name: chiefName,
                 gameId: cleanGid,
                 furnaceLevel: newFurnace,
                 stove_lv: newFurnace,
                 updatedAt: Date.now()
              };

              await set(ref(db, 'roster_live'), rosterObj);
              window.rosterCache = rosterObj;
           } catch(e) { console.warn("roster_live profile save error:", e); }

           currentUser.stove_lv = newFurnace;
           currentUser.furnaceLevel = newFurnace;
           currentUser.joinedDate = newJoinedDate;
           currentUser.bio = newBio;

           try {
              const token = await getAuthToken();
              const url = `${API_BASE_URL}?api=registerNewPlayer&gameId=${encodeURIComponent(cleanGid)}&name=${encodeURIComponent(chiefName)}&stove_lv=${encodeURIComponent(newFurnace)}&dateStarted=${encodeURIComponent(newJoinedDate)}&token=${encodeURIComponent(token)}`;
              fetch(url, { mode: 'no-cors' }).catch(e => null);
           } catch(e) {}

           window.showToast("Profile updated successfully!", "success");
           closeModal();
           views.account();
        } catch(e) {
           console.error("Save profile error:", e);
           window.showToast("Error saving profile. Try again.", "error");
           saveBtn.textContent = 'Save Changes';
        }
     };
  }
};

window.handleSyncCenturyGamesProfile = async () => {
  if (!currentUser) return;
  const syncBtn = document.getElementById('btnSyncCgProfile');
  const menuBtn = document.getElementById('idCardActionsMenuBtn');
  let originalMenuText = '';
  if (menuBtn) {
    originalMenuText = menuBtn.innerHTML;
    menuBtn.innerHTML = '🔄 Syncing...';
    menuBtn.disabled = true;
  }
  if (syncBtn) {
    syncBtn.disabled = true;
    syncBtn.innerHTML = '🔄 Syncing...';
  }

  try {
    const snap = await get(ref(db, `users/${currentUser.uid}`));
    const uData = (snap && snap.exists()) ? snap.val() : {};
    const token = uData.wos_cg_token || currentUser.wos_cg_token;

    if (!token) {
      window.openAccountHubVerifyModal();
      return;
    }

    const res = await fetch(`${API_BASE_URL}?api=syncProfileWithToken&id=${encodeURIComponent(currentUser.gameId)}&cgToken=${encodeURIComponent(token)}`);
    const data = await res.json();

    if (data && data.success) {
      const finalStove = data.stove_lv || currentUser.stove_lv || "";
      const updates = {
        stove_lv: finalStove,
        furnaceLevel: finalStove,
        section: data.section || currentUser.section || "2089",
        lastSyncedAt: new Date().toISOString(),
        centuryGamesVerified: true
      };
      if (data.avatar_image) updates.avatar_image = data.avatar_image;
      if (data.nickname && !/^\d+$/.test(data.nickname)) updates.name = data.nickname;

      await update(ref(db, `users/${currentUser.uid}`), updates);
      currentUser.stove_lv = finalStove;
      currentUser.furnaceLevel = finalStove;
      currentUser.section = updates.section;
      currentUser.centuryGamesVerified = true;
      if (updates.name) currentUser.name = updates.name;

      // Update roster_live in Firebase and in-memory cache
      try {
        const chiefName = (idToNameMap[currentUser.gameId] || currentUser.name || '').toString().trim();
        const cleanGid = (currentUser.gameId || '').toString().trim();
        const rosterSnap = await get(ref(db, 'roster_live')).catch(() => null);
        let rosterObj = (rosterSnap && rosterSnap.exists()) ? rosterSnap.val() : {};
        let foundKey = null;
        for (const [rk, rv] of Object.entries(rosterObj)) {
          if ((cleanGid && rv && rv.gameId && rv.gameId.toString().trim() === cleanGid) ||
              (chiefName && rk.toLowerCase() === chiefName.toLowerCase())) {
            foundKey = rk;
            break;
          }
        }
        const saveKey = foundKey || chiefName || cleanGid;
        rosterObj[saveKey] = {
          ...(rosterObj[saveKey] || {}),
          name: chiefName || updates.name || '',
          gameId: cleanGid,
          furnaceLevel: finalStove,
          stove_lv: finalStove,
          updatedAt: Date.now()
        };
        await set(ref(db, 'roster_live'), rosterObj);
        window.rosterCache = rosterObj;
      } catch(e) {}

      window.showToast("Profile synced successfully!", "success");
      if (views.account) views.account();
    } else if (data && (data.expired || data.code === 15030 || data.code === 101031008 || data.code === 15006 || (data.message && data.message.includes('未登录')) || (data.rawMsg && data.rawMsg.includes('未登录')))) {
      window.showToast("30-Day session expired. Please enter new in-game code to refresh.", "warning");
      window.openAccountHubVerifyModal();
    } else {
      const errMsg = window.translateWosApiError(data ? (data.message || data.rawMsg || "Failed to sync character stats.") : "Failed to sync character stats.", data ? data.code : null);
      window.showToast(errMsg, "error");
    }
  } catch (err) {
    console.error("Sync profile error:", err);
    window.showToast(window.translateWosApiError(err.message || "Failed to sync with game servers."), "error");
  } finally {
    if (syncBtn) {
      syncBtn.disabled = false;
      syncBtn.innerHTML = '🔄 Sync from Game';
    }
    if (menuBtn) {
      menuBtn.disabled = false;
      menuBtn.innerHTML = originalMenuText || '⚙️ Options ▾';
    }
  }
};

window.openAccountHubVerifyModal = () => {
  if (!currentUser) return;
  const oldModal = document.getElementById('accountHubVerifyModalOverlay');
  if (oldModal && oldModal.parentNode) oldModal.parentNode.removeChild(oldModal);

  const modalOverlay = document.createElement('div');
  modalOverlay.id = 'accountHubVerifyModalOverlay';
  modalOverlay.style.cssText = 'position:fixed; inset:0; background:rgba(15,23,42,0.85); backdrop-filter:blur(10px); z-index:99999; display:flex; align-items:center; justify-content:center; animation:fadeIn 0.2s ease;';

  modalOverlay.innerHTML = `
    <div class="card" style="width:92%; max-width:440px; background:linear-gradient(145deg, rgba(15,23,42,0.96), rgba(30,41,59,0.94)); border:1px solid rgba(56,189,248,0.35); padding:24px; border-radius:20px; box-shadow:0 25px 60px rgba(0,0,0,0.7); text-align:left; animation:zoomIn 0.2s forwards; color:var(--text-main);">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:16px; border-bottom:1px solid rgba(255,255,255,0.08); padding-bottom:12px;">
        <h3 style="margin:0; color:#fff; font-size:18px; font-weight:bold; display:flex; align-items:center; gap:8px;">
          🛡️ 30-Day Game Token Renewal
        </h3>
        <button onclick="document.getElementById('accountHubVerifyModalOverlay').remove()" style="background:none; border:none; color:var(--text-muted); font-size:26px; cursor:pointer; line-height:1;">&times;</button>
      </div>

      <p style="font-size:13px; color:var(--text-muted); margin:0 0 16px 0; line-height:1.5;">
        Verify Game ID <strong>${currentUser.gameId}</strong> to link your character directly to our database for <strong>30-day automatic stats syncing</strong> and in-game avatar loading.
      </p>

      <div style="text-align:center; margin-bottom:16px;">
        <button id="sendHubCodeBtn" style="background:linear-gradient(135deg, #0ea5e9, #0284c7); color:#fff; border:none; padding:10px 20px; border-radius:8px; font-weight:bold; font-size:14px; cursor:pointer; box-shadow:0 2px 10px rgba(14,165,233,0.3);">
          📩 Send Code to In-Game Mail
        </button>
      </div>

      <div id="hubVerifyCodeSection" style="display:none; background:rgba(255,255,255,0.03); border:1px solid var(--border); border-radius:12px; padding:14px; margin-bottom:14px;">
        <label style="display:block; font-size:12px; font-weight:bold; color:var(--text-muted); margin-bottom:6px; text-transform:uppercase;">
          Enter 6-Digit In-Game Code
        </label>
        <div style="display:flex; gap:8px;">
          <input type="text" id="hubCaptchaInput" maxlength="8" placeholder="e.g. 123456" style="flex:1; padding:9px 12px; border-radius:8px; border:1px solid var(--border); background:var(--bg-main); color:#fff; font-size:15px; font-family:monospace; letter-spacing:2px; text-align:center;">
          <button id="submitHubCodeBtn" style="background:var(--accent); color:#fff; border:none; padding:9px 16px; border-radius:8px; font-weight:bold; font-size:13px; cursor:pointer;">
            Verify & Bind
          </button>
        </div>
        <div id="hubVerifyFeedback" style="font-size:12px; margin-top:8px; display:none;"></div>
      </div>

      <div style="display:flex; justify-content:flex-end;">
        <button onclick="document.getElementById('accountHubVerifyModalOverlay').remove()" style="background:rgba(255,255,255,0.08); border:1px solid rgba(255,255,255,0.15); color:#cbd5e1; padding:8px 16px; border-radius:8px; cursor:pointer; font-size:13px;">
          Cancel
        </button>
      </div>
    </div>
  `;

  document.body.appendChild(modalOverlay);

  const sendBtn = document.getElementById('sendHubCodeBtn');
  const codeSection = document.getElementById('hubVerifyCodeSection');
  const submitCodeBtn = document.getElementById('submitHubCodeBtn');
  const codeInput = document.getElementById('hubCaptchaInput');
  const feedback = document.getElementById('hubVerifyFeedback');

  if (sendBtn) {
    sendBtn.addEventListener('click', async () => {
      sendBtn.disabled = true;
      sendBtn.textContent = 'Sending Code...';
      try {
        const res = await fetch(`${API_BASE_URL}?api=sendGameCaptcha&id=${encodeURIComponent(currentUser.gameId)}`);
        const data = await res.json();
        if (data && data.success) {
          sendBtn.textContent = '🔄 Resend Code';
          sendBtn.disabled = false;
          if (codeSection) codeSection.style.display = 'block';
          if (feedback) {
            feedback.style.display = 'block';
            feedback.style.color = '#38bdf8';
            feedback.textContent = 'Code dispatched! Check your Whiteout Survival system mail.';
          }
          window.showToast("📩 Verification code sent to your in-game mailbox!", "info");
          if (codeInput) setTimeout(() => codeInput.focus(), 60);
        } else {
          throw new Error(window.translateWosApiError(data.message || 'Failed to dispatch in-game code.', data.code));
        }
      } catch (err) {
        sendBtn.disabled = false;
        sendBtn.textContent = '📩 Send Code to In-Game Mail';
        const msg = window.translateWosApiError(err.message || 'Error communicating with game servers.');
        if (feedback) {
          feedback.style.display = 'block';
          feedback.style.color = 'var(--danger)';
          feedback.textContent = msg;
        }
        window.showToast(msg, 'error');
      }
    });
  }

  if (submitCodeBtn && codeInput) {
    const handleVerify = async () => {
      const code = codeInput.value.trim();
      if (!code || code.length < 4) {
        if (feedback) {
          feedback.style.display = 'block';
          feedback.style.color = 'var(--danger)';
          feedback.textContent = 'Please enter valid 6-digit code.';
        }
        return;
      }

      submitCodeBtn.disabled = true;
      submitCodeBtn.textContent = 'Verifying...';
      if (feedback) feedback.style.display = 'none';

      try {
        const res = await fetch(`${API_BASE_URL}?api=verifyGameCaptcha&id=${encodeURIComponent(currentUser.gameId)}&code=${encodeURIComponent(code)}`);
        const data = await res.json();

        if (data && data.success && data.token) {
          const updates = {
            wos_cg_token: data.token,
            section: data.section || currentUser.section || "2089",
            stove_lv: data.stove_lv || currentUser.stove_lv || "",
            verifiedAt: new Date().toISOString(),
            centuryGamesVerified: true
          };
          if (data.avatar_image) {
            updates.avatar_image = data.avatar_image;
            if (currentUser.avatarPreference !== 'custom') {
              try {
                await uploadAvatar(currentUser.gameId, data.avatar_image);
                avatarMap[currentUser.gameId] = data.avatar_image;
              } catch(e) { console.warn("Failed to auto-sync avatar:", e); }
            }
          }
          if (data.nickname && !/^\d+$/.test(data.nickname)) updates.name = data.nickname;

          await update(ref(db, `users/${currentUser.uid}`), updates);
          currentUser.wos_cg_token = data.token;
          currentUser.section = updates.section;
          currentUser.stove_lv = updates.stove_lv;
          currentUser.centuryGamesVerified = true;

          modalOverlay.remove();
          window.showToast("🎉 Character verified & 30-day sync token bound!", "success");
          if (views.account) views.account();
        } else {
          throw new Error(window.translateWosApiError(data.message || 'Invalid or expired code.', data.code));
        }
      } catch (err) {
        submitCodeBtn.disabled = false;
        submitCodeBtn.textContent = 'Verify & Bind';
        const msg = window.translateWosApiError(err.message || 'Verification failed.');
        if (feedback) {
          feedback.style.display = 'block';
          feedback.style.color = 'var(--danger)';
          feedback.textContent = msg;
        }
        window.showToast(msg, 'error');
      }
    };

    submitCodeBtn.addEventListener('click', handleVerify);
    codeInput.addEventListener('keypress', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleVerify();
      }
    });
  }
};

