// ============================================================================
// UNIFIED SINGLE-CANVAS FIRE CRYSTAL ENGINE (v2.5.56)
// Renders both Badge Image & Symmetrical Flame Physics in a Single 2D Context
// ============================================================================
(function() {
  const colorPalettes = {
    1: { outer: '#ef4444', core: '#fee2e2', glow: '#dc2626', name: 'Crimson' },
    2: { outer: '#f97316', core: '#ffedd5', glow: '#ea580c', name: 'Inferno' },
    3: { outer: '#eab308', core: '#fef9c3', glow: '#ca8a04', name: 'Solar' },
    4: { outer: '#10b981', core: '#ecfdf5', glow: '#059669', name: 'Verdant' },
    5: { outer: '#06b6d4', core: '#cff4fc', glow: '#0891b2', name: 'Frostfire' },
    6: { outer: '#3b82f6', core: '#eff6ff', glow: '#2563eb', name: 'Azure' },
    7: { outer: '#a855f7', core: '#fae8ff', glow: '#9333ea', name: 'Void' },
    8: { outer: '#ec4899', core: '#fdf2f8', glow: '#db2777', name: 'Abyssal' },
    9: { outer: '#84cc16', core: '#f7fee7', glow: '#65a30d', name: 'Venom' },
    10: { outer: '#ffd700', core: '#ffffff', glow: '#ff8c00', name: 'Imperial' }
  };

  const badgeImageCache = new Map();
  function getBadgeImage(fcNum) {
    if (badgeImageCache.has(fcNum)) return badgeImageCache.get(fcNum);
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.src = `./badges/fc${fcNum}.png?v=2.5.56`;
    badgeImageCache.set(fcNum, img);
    return img;
  }

  class FlameWisp {
    constructor(cx, cy, drawW, drawH, colors, isBurst = false) {
      const scale = drawW / 130;
      
      // Exact pixel-aligned shield contour vertices (measured from 1024x1024 assets)
      const v = [
        { x: cx, y: cy - (drawH * 0.433) },                                  // Top Point
        { x: cx + (drawW * 0.367), y: cy - (drawH * 0.226) },               // Top Right Corner
        { x: cx + (drawW * 0.367), y: cy + (drawH * 0.226) },               // Bottom Right Corner
        { x: cx, y: cy + (drawH * 0.433) },                                  // Bottom Point
        { x: cx - (drawW * 0.367), y: cy + (drawH * 0.226) },               // Bottom Left Corner
        { x: cx - (drawW * 0.367), y: cy - (drawH * 0.226) }                // Top Left Corner
      ];

      // Pick a random edge segment along the shield (0 to 5)
      const edge = Math.floor(Math.random() * 6);
      const pA = v[edge];
      const pB = v[(edge + 1) % 6];
      const t = Math.random();
      
      // Interpolate along the exact shield border
      this.x = pA.x * (1 - t) + pB.x * t + (Math.random() - 0.5) * (3 * scale);
      this.y = pA.y * (1 - t) + pB.y * t + (Math.random() - 0.5) * (3 * scale);
      
      // Outward vector pointing straight out from the facet normal
      const edgeDx = pB.x - pA.x;
      const edgeDy = pB.y - pA.y;
      let nx = edgeDy;
      let ny = -edgeDx;
      const nLen = Math.hypot(nx, ny) || 1;
      nx /= nLen;
      ny /= nLen;

      if (nx * (this.x - cx) + ny * (this.y - cy) < 0) {
        nx = -nx;
        ny = -ny;
      }

      const speedMult = isBurst ? 1.6 : 1.0;
      this.vx = (nx * 1.6 * speedMult + (Math.random() - 0.5) * 0.8) * scale;
      this.vy = (ny * 0.6 * speedMult - (Math.random() * 2.4 + 1.2) * speedMult) * scale;
      
      this.size = (Math.random() * 9 + 4.5) * scale * (isBurst ? 1.3 : 1.0);
      this.scale = scale;
      this.alpha = 1.0;
      this.decay = (Math.random() * 0.018 + 0.010) * (isBurst ? 0.9 : 1.0);
      this.waveSpeed = Math.random() * 0.12 + 0.06;
      this.waveAngle = Math.random() * Math.PI * 2;
      
      this.colors = colors;
    }

    update() {
      this.waveAngle += this.waveSpeed;
      this.x += this.vx + Math.sin(this.waveAngle) * (1.1 * this.scale);
      this.y += this.vy;
      this.size *= 0.96;
      this.alpha -= this.decay;
    }

    draw(ctx) {
      if (this.alpha <= 0 || this.size <= 0.8) return;

      ctx.save();
      ctx.globalAlpha = Math.max(0, this.alpha);
      
      ctx.beginPath();
      ctx.shadowBlur = 10 * this.scale;
      ctx.shadowColor = this.colors.glow;
      
      ctx.fillStyle = this.colors.outer;
      ctx.ellipse(this.x, this.y, this.size * 0.6, this.size * 1.2, Math.sin(this.waveAngle) * 0.3, 0, Math.PI * 2);
      ctx.fill();
      
      ctx.beginPath();
      ctx.fillStyle = this.colors.core;
      ctx.ellipse(this.x, this.y + (2 * this.scale), this.size * 0.3, this.size * 0.6, 0, 0, Math.PI * 2);
      ctx.fill();
      
      ctx.restore();
    }
  }

  const activeUnifiedInstances = new Map();

  function attachUnifiedFcEngine(canvas) {
    if (activeUnifiedInstances.has(canvas)) return activeUnifiedInstances.get(canvas);

    const fcNum = parseInt(canvas.getAttribute('data-fc'), 10) || 1;
    const badgeSize = parseInt(canvas.getAttribute('data-size'), 10) || 130;
    const colors = colorPalettes[fcNum] || colorPalettes[1];
    const img = getBadgeImage(fcNum);

    const ctx = canvas.getContext('2d');
    const dpr = window.devicePixelRatio || 1;
    
    // Display dimensions
    const displaySize = Math.round(badgeSize * 1.45);
    canvas.width = Math.round(displaySize * dpr);
    canvas.height = Math.round(displaySize * dpr);
    canvas.style.width = displaySize + 'px';
    canvas.style.height = displaySize + 'px';

    const cx = displaySize / 2;
    const cy = displaySize / 2;

    let wisps = [];
    let isActive = false;
    let animFrame = null;
    let scaleAnim = 1.0;
    let targetScale = 1.0;
    let roarTimeout = null;

    function render() {
      ctx.save();
      ctx.scale(dpr, dpr);
      ctx.clearRect(0, 0, displaySize, displaySize);

      // Smooth spring scale interpolation
      scaleAnim += (targetScale - scaleAnim) * 0.2;
      const curDrawW = badgeSize * scaleAnim;
      const curDrawH = badgeSize * scaleAnim;
      const curDrawX = cx - (curDrawW / 2);
      const curDrawY = cy - (curDrawH / 2);

      // 1. Draw Background Radial Glow when active
      if (isActive || scaleAnim > 1.01) {
        const glowRad = (badgeSize * 0.7) * scaleAnim;
        const grad = ctx.createRadialGradient(cx, cy, badgeSize * 0.2, cx, cy, glowRad);
        grad.addColorStop(0, colors.glow);
        grad.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.save();
        ctx.globalAlpha = 0.45 * Math.min(1, scaleAnim);
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(cx, cy, glowRad, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }

      // 2. Spawn wisps when active
      if (isActive) {
        if (Math.random() < 0.75) {
          wisps.push(new FlameWisp(cx, cy, curDrawW, curDrawH, colors, false));
        }
      }

      // 3. Draw Flame Wisps (Behind & Around)
      for (let i = wisps.length - 1; i >= 0; i--) {
        wisps[i].update();
        wisps[i].draw(ctx);
        if (wisps[i].alpha <= 0 || wisps[i].size <= 0.8) {
          wisps.splice(i, 1);
        }
      }

      // 4. Draw Center Shield Badge Sprite
      if (img.complete && img.naturalWidth > 0) {
        ctx.save();
        ctx.shadowColor = colors.glow;
        ctx.shadowBlur = Math.max(8, Math.round(badgeSize / 4));
        ctx.drawImage(img, curDrawX, curDrawY, curDrawW, curDrawH);
        ctx.restore();
      }

      ctx.restore();

      if (isActive || wisps.length > 0 || Math.abs(targetScale - scaleAnim) > 0.005) {
        animFrame = requestAnimationFrame(render);
      } else {
        animFrame = null;
      }
    }

    function triggerHaptic() {
      if (typeof navigator !== 'undefined' && navigator.vibrate) {
        try { navigator.vibrate([18, 30, 22]); } catch (e) {}
      }
      try {
        const AudioCtx = window.AudioContext || window.webkitAudioContext;
        if (AudioCtx) {
          if (!window._appleHapticCtx) window._appleHapticCtx = new AudioCtx();
          const ac = window._appleHapticCtx;
          if (ac.state === 'suspended') ac.resume();
          const osc = ac.createOscillator();
          const gain = ac.createGain();
          osc.type = 'sine';
          osc.frequency.setValueAtTime(160, ac.currentTime);
          osc.frequency.exponentialRampToValueAtTime(40, ac.currentTime + 0.025);
          gain.gain.setValueAtTime(0.35, ac.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.001, ac.currentTime + 0.025);
          osc.connect(gain);
          gain.connect(ac.destination);
          osc.start();
          osc.stop(ac.currentTime + 0.025);
        }
      } catch (e) {}
    }

    function start() {
      isActive = true;
      targetScale = 1.10;
      if (!animFrame) animFrame = requestAnimationFrame(render);
    }

    function stop() {
      isActive = false;
      targetScale = 1.0;
      if (roarTimeout) {
        clearTimeout(roarTimeout);
        roarTimeout = null;
      }
    }

    function burst() {
      triggerHaptic();
      start();
      targetScale = 0.94;
      setTimeout(() => {
        if (isActive) targetScale = 1.12;
      }, 120);
      const curDrawW = badgeSize * 1.10;
      const curDrawH = badgeSize * 1.10;
      for (let i = 0; i < 14; i++) {
        wisps.push(new FlameWisp(cx, cy, curDrawW, curDrawH, colors, true));
      }
      if (roarTimeout) clearTimeout(roarTimeout);
      roarTimeout = setTimeout(() => {
        stop();
      }, 3500);
    }

    canvas.addEventListener('mouseenter', start);
    canvas.addEventListener('mouseleave', stop);
    canvas.addEventListener('touchstart', (e) => {
      e.preventDefault();
      burst();
    }, { passive: false });
    canvas.addEventListener('click', burst);

    // Initial static render on load
    if (img.complete) {
      render();
    } else {
      img.onload = () => render();
    }

    const instance = { start, stop, burst, render };
    activeUnifiedInstances.set(canvas, instance);
    return instance;
  }

  // Global Auto-Init Scanner for all Unified Badges in DOM
  window.initUnifiedFcBadges = () => {
    document.querySelectorAll('.fc-unified-badge').forEach(canvas => {
      attachUnifiedFcEngine(canvas);
    });
  };

  // Run on DOM events & dynamic view changes
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', window.initUnifiedFcBadges);
  } else {
    window.initUnifiedFcBadges();
  }

  document.addEventListener('mouseover', (e) => {
    const canvas = e.target.closest('.fc-unified-badge');
    if (canvas) {
      const inst = attachUnifiedFcEngine(canvas);
      if (inst) inst.start();
    }
  });

  document.addEventListener('touchstart', (e) => {
    const canvas = e.target.closest('.fc-unified-badge');
    if (canvas) {
      const inst = attachUnifiedFcEngine(canvas);
      if (inst) inst.burst();
    }
  }, { passive: true });

  // Periodically scan for newly rendered badges (e.g. after view switches)
  setInterval(() => {
    document.querySelectorAll('.fc-unified-badge').forEach(canvas => {
      if (!activeUnifiedInstances.has(canvas)) {
        attachUnifiedFcEngine(canvas);
      }
    });
  }, 1200);
})();

// ============================================================================
// AUTOMATIC REAL-APP UPDATE NOTIFICATION SYSTEM (v1.87.0)
// ============================================================================
(function() {
  const CURRENT_BUILD_VERSION = (pkg && pkg.version) ? pkg.version : "1.87.0";

  function isVersionOutdated(localVer, serverVer) {
    if (!localVer || !serverVer) return false;
    const lParts = localVer.split('.').map(n => parseInt(n, 10) || 0);
    const sParts = serverVer.split('.').map(n => parseInt(n, 10) || 0);
    for (let i = 0; i < Math.max(lParts.length, sParts.length); i++) {
      const l = lParts[i] || 0;
      const s = sParts[i] || 0;
      if (s > l) return true;
      if (s < l) return false;
    }
    return false;
  }

  function showUpdateBanner(updateData) {
    if (document.getElementById('app-update-modal-banner')) return;
    if (localStorage.getItem('wos_dismissed_update') === updateData.version) return;
    if (localStorage.getItem('wos_app_version') === updateData.version) return;

    const banner = document.createElement('div');
    banner.id = 'app-update-modal-banner';
    banner.style.cssText = `
      position: fixed;
      bottom: 24px;
      left: 50%;
      transform: translateX(-50%) translateY(120%);
      width: calc(100% - 32px);
      max-width: 480px;
      background: linear-gradient(135deg, rgba(15, 23, 42, 0.96), rgba(30, 41, 59, 0.98));
      border: 1px solid rgba(255, 215, 0, 0.6);
      box-shadow: 0 20px 50px rgba(0, 0, 0, 0.8), 0 0 30px rgba(255, 215, 0, 0.25);
      border-radius: 20px;
      padding: 20px;
      z-index: 999999;
      color: #f1f5f9;
      font-family: system-ui, -apple-system, sans-serif;
      backdrop-filter: blur(16px);
      transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    `;

    const notesList = (updateData.notes || [])
      .map(n => `<li style="margin-bottom: 4px; font-size: 0.86rem; color: #cbd5e1;">✨ ${n}</li>`)
      .join('');

    banner.innerHTML = `
      <div style="display:flex; align-items:center; justify-content:space-between; margin-bottom: 12px;">
        <div style="display:flex; align-items:center; gap: 10px;">
          <span style="font-size: 1.5rem; filter: drop-shadow(0 0 8px #ffd700);">🚀</span>
          <div>
            <div style="font-weight: 800; font-size: 1.05rem; color: #ffd700;">App Update Available!</div>
            <div style="font-size: 0.8rem; color: #94a3b8;">New Version v${updateData.version} is ready</div>
          </div>
        </div>
        <span style="background: rgba(255, 215, 0, 0.15); border: 1px solid #ffd700; color: #ffd700; font-size: 0.78rem; font-weight: 700; padding: 3px 10px; border-radius: 12px;">v${updateData.version}</span>
      </div>
      <div style="margin-bottom: 16px; background: rgba(0,0,0,0.25); padding: 10px 14px; border-radius: 12px; border: 1px solid rgba(255,255,255,0.06);">
        <ul style="list-style: none; margin: 0; padding: 0;">${notesList}</ul>
      </div>
      <div style="display:flex; gap: 10px;">
        <button id="btn-force-update-app" style="flex: 2; background: linear-gradient(135deg, #ffd700, #ff8c00); border: none; color: #0f172a; font-weight: 800; font-size: 0.95rem; padding: 12px; border-radius: 14px; cursor: pointer; box-shadow: 0 4px 15px rgba(255, 215, 0, 0.4); transition: transform 0.2s;">
          ⚡ Update App Now
        </button>
        <button id="btn-dismiss-update-app" style="flex: 1; background: rgba(255,255,255,0.08); border: 1px solid rgba(255,255,255,0.15); color: #cbd5e1; font-weight: 600; font-size: 0.9rem; padding: 12px; border-radius: 14px; cursor: pointer;">
          Later
        </button>
      </div>
    `;

    document.body.appendChild(banner);
    setTimeout(() => {
      banner.style.transform = 'translateX(-50%) translateY(0)';
    }, 100);

    document.getElementById('btn-force-update-app').addEventListener('click', async () => {
      localStorage.setItem('wos_app_version', updateData.version);
      if ('serviceWorker' in navigator) {
        try {
          const regs = await navigator.serviceWorker.getRegistrations();
          for (let r of regs) await r.unregister();
        } catch (e) {}
      }
      if ('caches' in window) {
        try {
          const keys = await caches.keys();
          for (let k of keys) await caches.delete(k);
        } catch (e) {}
      }
      window.location.href = window.location.pathname + '?v=' + Date.now() + window.location.hash;
    });

    document.getElementById('btn-dismiss-update-app').addEventListener('click', () => {
      localStorage.setItem('wos_dismissed_update', updateData.version);
      banner.style.transform = 'translateX(-50%) translateY(120%)';
      setTimeout(() => banner.remove(), 400);
    });
  }

  async function checkAppVersion() {
    try {
      const res = await fetch(`/version.json?t=${Date.now()}`, { cache: 'no-store' });
      if (!res.ok) return;
      const data = await res.json();
      if (data && data.version) {
        if (localStorage.getItem('wos_dismissed_update') === data.version) return;
        if (isVersionOutdated(CURRENT_BUILD_VERSION, data.version)) {
          showUpdateBanner(data);
        } else {
          localStorage.setItem('wos_app_version', data.version);
        }
      }
    } catch (err) {}
  }

  window.checkAppVersion = checkAppVersion;

  // Immediate check & DOMContentLoaded check
  checkAppVersion();
  window.addEventListener('DOMContentLoaded', () => {
    setTimeout(checkAppVersion, 1000);
  });

  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') {
      checkAppVersion();
    }
  });

  setInterval(checkAppVersion, 30000);
})();

